<?php session_start();if(isset($_SESSION['user_id'])){header('Location: '.(($_SESSION['user_role']??'')==='admin'?'admin/index.php':'dashboard.php'));exit;}require_once 'includes/header.php'; ?>
<section class="auth-page"><div class="auth-image"><div><span class="eyebrow">VS TRAVELLS</span><h1>Good journeys start with the right ride.</h1><p>Sign in to manage requests, payments and bookings.</p></div></div><div class="auth-panel"><form id="loginForm" class="auth-form"><span class="eyebrow dark">WELCOME BACK</span><h2>Sign in to your account</h2><p class="muted">Enter your registered email and password.</p><div id="msg"></div><label>Email address<input type="email" id="email" required placeholder="you@example.com"></label><label>Password<input type="password" id="password" required placeholder="••••••••"></label><button class="btn wide">Sign in</button><p class="auth-switch">New to VS Travells? <a href="register.php">Create an account</a></p></form></div></section>
<script>loginForm.onsubmit=async e=>{e.preventDefault();const r=await fetch('api/auth/login.php',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'include',body:JSON.stringify({email:email.value,password:password.value})}),j=await r.json();msg.innerHTML=`<div class="message ${j.success?'success':'error'}">${j.message}</div>`;if(j.success)setTimeout(()=>location.href=j.data.role==='admin'?'admin/index.php':'dashboard.php',500)}</script>
